// 所有借用局限同一候选调用；不从今日玩家位置/旧claim猜外层Advance提交者。
#include "visit_message_receipt_world.hpp"
#include "visit_reception_world.hpp"
#include "visit_message_receipt_native.hpp"
#include "resident/kernel/exact_complete_world.hpp"
#include "resident/kernel/world_bundle.hpp"
namespace hanmo::resident {namespace {
Status ready(const WorldBundle& w){return w.catalog->visit_message_receipts_enabled&&w.dynamic_enabled()&&w.catalog->director&&w.catalog->interaction&&w.catalog->interaction->visit_messages&&w.interaction.visit_messages&&w.interaction.visit_message_receipts?common_success():common_failure("VisitMessageReceiptProfileRequired");}
VisitMessageReceiptRead legacy_read(const WorldBundle& w){return {*w.interaction.visit_messages,*w.catalog->interaction->visit_messages,w.catalog->director?w.catalog->director->visit_reception.get():nullptr,w.interaction.visit_reception_claims?&*w.interaction.visit_reception_claims:nullptr,[&w](Integer tick,const StableId& fact){return read_visit_message_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);},[&w](Integer tick,const StableId& fact){return read_visit_message_advance_submitter_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);},w.catalog->director->dynamic_subjects?VisitMessageSubmitterMode::controlled_player:VisitMessageSubmitterMode::legacy_actor};}
struct Access {std::unique_ptr<CompleteExactWorldBindingOwner> complete;std::unique_ptr<NativeVisitMessageReceiptRead> native;std::optional<VisitMessageReceiptRead> legacy;const VisitMessageReceiptRead* context=nullptr;};
Outcome<Access>read(const WorldBundle&w,const CompleteExactWorldReadBindings*supplied){Access access;if(w.interaction.visit_messages->version>=2||w.interaction.visit_message_receipts->version==2){const auto*b=supplied;if(!b){auto lease=w.complete_exact_time_bindings();if(!lease.ok)return {false,{},lease.error};access.complete=std::move(lease.value);if(!access.complete)return {false,{},common_failure("VisitMessageReceiptCompleteLeaseRequired",{},ErrorKind::unsupported_capability).error};b=&access.complete->reads();}if(!b->family_control_sources)return {false,{},common_failure("VisitMessageReceiptFamilyControlRequired",{},ErrorKind::unsupported_capability).error};auto native=NativeVisitMessageReceiptRead::create(w,*b->family_control_sources);if(!native.ok)return {false,{},native.error};access.native=std::move(native.value);auto context=access.native->context();if(!context.ok)return {false,{},context.error};access.context=context.value;}else{access.legacy.emplace(legacy_read(w));}// legacy pointer is resolved by the caller after this movable wrapper settles.
 return {true,std::move(access),{}};}
const VisitMessageReceiptRead&context(const Access&access){return access.native?*access.context:*access.legacy;}

}
Status validate_visit_message_receipt_world(const WorldBundle& w,const CompleteExactWorldReadBindings*actual){auto valid=validate_visit_message_receipt_layout(w.catalog->identity.module_versions,w.catalog->visit_message_receipts_enabled,w.catalog->interaction&&bool(w.catalog->interaction->visit_messages),w.interaction.visit_message_receipts?&*w.interaction.visit_message_receipts:nullptr);if(!valid.ok||!w.catalog->visit_message_receipts_enabled)return valid;valid=ready(w);if(!valid.ok)return valid;auto access=read(w,actual);return access.ok?validate_visit_message_actual_results(w.common,*w.interaction.visit_message_receipts,context(access.value)):Status{false,{},access.error};}
Status guard_visit_message_receipt_producer_world(const WorldBundle&w,const StableId&actor,const VisitMessageCommand&command,const CompleteExactWorldReadBindings*actual){
 if(!w.catalog->visit_message_receipts_enabled)return common_success();auto valid=ready(w);if(!valid.ok)return valid;
 std::optional<Access> retained;StableId player=w.common.state().metadata.player_actor_id;
 if(w.interaction.visit_message_receipts->version==2){auto source=read(w,actual);if(!source.ok)return {false,{},source.error};retained.emplace(std::move(source.value));if(!actual)actual=&retained->complete->reads();if(!actual->family_control_sources)return common_failure("VisitMessageReceiptFamilyControlRequired",{},ErrorKind::unsupported_capability);auto control=read_current_profile_control(*actual->family_control_sources);if(!control.ok)return {false,{},control.error};player=control.value.actor_id;}
 if(actor==player)return common_success();if(w.catalog->director->subjects2&&w.interaction.visit_message_receipts->version!=2)return common_failure("VisitMessageDirectorActorReceipt2Required",actor,ErrorKind::unsupported_capability);
 if(!w.catalog->director->visit_reception||!w.interaction.visit_reception_claims)return common_failure("VisitMessageOriginalNpcClaimRequired",actor);const auto*intent=visit_reception_actor_intent(*w.catalog->director->visit_reception,actor);if(!intent)return common_failure("VisitMessageOriginalNpcClaimRequired",actor);
 const bool accepted=std::visit([&](const auto&c){using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,LeaveVisitMessage>)return intent->purpose=="deposit"&&intent->message_policy_id==c.policy_id;else if constexpr(std::is_same_v<T,ReceiveVisitMessage>){const auto*message=w.interaction.visit_messages->posted.find(c.message_fact_id);return intent->purpose=="receive"&&message&&message->policy_id==intent->message_policy_id;}else return false;},command);if(!accepted)return common_failure("VisitMessageOriginalNpcClaimRequired",actor);
 auto conversation=visit_reception_conversation_world(w,actor,actual);if(!conversation.ok)return {false,{},conversation.error};if(!conversation.value)return common_failure("VisitMessageOriginalNpcClaimRequired",actor);
 if(w.interaction.visit_message_receipts->version==2||!w.catalog->director->dynamic_subjects)return common_success();auto possible=visit_message_npc_receipt_available(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr);if(!possible.ok)return {false,{},possible.error};return possible.value?common_success():common_failure("VisitMessageControlChangeAwaitNextTick",actor);
}
Outcome<VisitMessageResultSources> visit_message_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){if(!after.catalog->visit_message_receipts_enabled){if(before.catalog->visit_message_receipts_enabled||before.interaction.visit_message_receipts||after.interaction.visit_message_receipts)return {false,{},common_failure("VisitMessageReceiptProfileMismatch").error};return {true,{}, {}};}auto valid=ready(before);if(!valid.ok)return {false,{},valid.error};valid=ready(after);if(!valid.ok)return {false,{},valid.error};Integer from=before.common.tick(),through=after.common.tick();if(after.interaction.visit_messages->version>=2||after.interaction.visit_message_receipts->version==2){auto first=before.actual_phase_moment(),last=after.actual_phase_moment();if(!first.ok)return {false,{},first.error};if(!last.ok)return {false,{},last.error};from=first.value.half_day_tick;through=last.value.half_day_tick;}auto added=visit_message_new_result_sources(*before.interaction.visit_messages,*after.interaction.visit_messages,*before.interaction.visit_message_receipts,*after.interaction.visit_message_receipts,actor,kind,details,through,from);if(!added.ok)return {false,{},added.error};return {true,{std::move(added.value),from},{}};}
Status bind_visit_message_result_world(WorldBundle& w,const VisitMessageResultSources& batch,const StableId& actor,Integer sequence,const CommitResult& result,const CompleteExactWorldReadBindings*actual){if(!w.catalog->visit_message_receipts_enabled)return batch.fact_ids.empty()?common_success():common_failure("VisitMessageReceiptProfileRequired");auto valid=ready(w);if(!valid.ok)return valid;auto access=read(w,actual);return access.ok?bind_visit_message_actual_result(w.common,*w.interaction.visit_message_receipts,context(access.value),batch.fact_ids,actor,sequence,result,batch.from_tick):Status{false,{},access.error};}
Outcome<MomentOwnerSource>read_visit_message_director_command_effect_world(const WorldBundle&before,const WorldBundle&after,const StableId&actor,const StableId&kind,const ReceiptDetails&details,const CompleteExactWorldReadBindings*actual){auto valid=ready(after);if(!valid.ok)return {false,{},valid.error};if(after.interaction.visit_message_receipts->version!=2||before.catalog.get()!=after.catalog.get())return {false,{},common_failure("VisitMessageDirectorActorReceipt2Required",{},ErrorKind::unsupported_capability).error};auto delta=visit_message_new_result_world(before,after,actor,kind,details);if(!delta.ok)return {false,{},delta.error};if(delta.value.fact_ids.size()!=1)return {false,{},common_failure("VisitMessageActualNewSourceRequired",actor,ErrorKind::internal).error};auto access=read(after,actual);if(!access.ok)return {false,{},access.error};const auto&r=context(access.value);valid=validate_visit_messages(after.common,r.messages,r.catalog,*after.catalog->interaction,r.actual_clock);if(!valid.ok)return {false,{},valid.error};auto now=after.actual_phase_moment();if(!now.ok)return {false,{},now.error};return read_visit_message_director_command_effect(after.common,r,delta.value.fact_ids.front(),actor,kind,details,now.value);}
Status validate_visit_message_director_actor_effect_world(const WorldBundle&w,const StableId&actor,const SourceRef&source,const CompleteExactWorldReadBindings*actual){auto valid=ready(w);if(!valid.ok)return valid;auto access=read(w,actual);if(!access.ok)return {false,{},access.error};const auto&r=context(access.value);valid=validate_visit_messages(w.common,r.messages,r.catalog,*w.catalog->interaction,r.actual_clock);if(!valid.ok)return valid;return validate_visit_message_director_actor_effect(w.common,*w.interaction.visit_message_receipts,r,actor,source);}
Status bind_visit_message_director_actor_result_world(WorldBundle&w,const DirectorAdoptionResult2&adoption,const CompleteExactWorldReadBindings*actual){if(!adoption.accepted_command)return common_failure("VisitMessageActualActorAdoptionRequired",{},ErrorKind::internal);const auto&source=adoption.accepted_command->actual_effect.source_ref;if(source.domain!="visit_messages"||(source.kind!=visit_message_posted_kind&&source.kind!=visit_message_received_kind&&source.kind!=visit_message_withdrawn_kind))return common_success();auto valid=ready(w);if(!valid.ok)return valid;auto access=read(w,actual);return access.ok?bind_visit_message_director_actor_result(w.common,*w.interaction.visit_message_receipts,context(access.value),adoption):Status{false,{},access.error};}

}
